alter table public.admin_content drop constraint if exists admin_content_content_type_check;
alter table public.admin_content add constraint admin_content_content_type_check check (content_type in ('BLOG', 'ANNOUNCEMENT', 'ABOUT', 'PRIVACY', 'CONTACT', 'HELP', 'FAQ', 'USER_EDU', 'SELLER_EDU', 'RETURN_POLICY', 'SELLER_PRIVACY', 'TERMS', 'SETTINGS'));

create or replace function public.admin_upsert_content(
  p_admin_id text, p_id uuid, p_content_type text, p_title text, p_slug text,
  p_excerpt text, p_body text, p_status text, p_cover_image_url text default null,
  p_seo_title text default null, p_seo_description text default null, p_sort_order integer default 0
) returns void as $$
begin
  perform public.admin_assert(p_admin_id);
  if p_content_type not in ('BLOG', 'ANNOUNCEMENT', 'ABOUT', 'PRIVACY', 'CONTACT', 'HELP', 'FAQ', 'USER_EDU', 'SELLER_EDU', 'RETURN_POLICY', 'SELLER_PRIVACY', 'TERMS', 'SETTINGS') then raise exception 'Invalid content type'; end if;
  if p_status not in ('DRAFT', 'PUBLISHED', 'ARCHIVED') then raise exception 'Invalid content status'; end if;
  if coalesce(trim(p_title), '') = '' or coalesce(trim(p_slug), '') = '' then raise exception 'Title and slug are required'; end if;
  if p_id is null then
    insert into public.admin_content(content_type, title, slug, excerpt, body, status, author_id, cover_image_url, seo_title, seo_description, published_at, sort_order)
    values (p_content_type, trim(p_title), lower(trim(p_slug)), coalesce(p_excerpt, ''), coalesce(p_body, ''), p_status, coalesce(current_setting('request.jwt.claim.sub', true), null), nullif(trim(coalesce(p_cover_image_url, '')), ''), nullif(trim(coalesce(p_seo_title, '')), ''), nullif(trim(coalesce(p_seo_description, '')), ''), case when p_status = 'PUBLISHED' then now() else null end, coalesce(p_sort_order, 0));
  else
    update public.admin_content set content_type=p_content_type, title=trim(p_title), slug=lower(trim(p_slug)), excerpt=coalesce(p_excerpt, ''), body=coalesce(p_body, ''), status=p_status, cover_image_url=nullif(trim(coalesce(p_cover_image_url, '')), ''), seo_title=nullif(trim(coalesce(p_seo_title, '')), ''), seo_description=nullif(trim(coalesce(p_seo_description, '')), ''), published_at=case when p_status='PUBLISHED' then coalesce(published_at, now()) else published_at end, sort_order=coalesce(p_sort_order, 0), updated_at=now() where id=p_id;
    if not found then raise exception 'Content not found'; end if;
  end if;
end;
$$ language plpgsql security definer set search_path = public;

insert into public.admin_content(content_type, title, slug, excerpt, body, status, seo_title, seo_description, published_at)
select 'SELLER_PRIVACY', 'Seller Privacy Policy', 'seller-privacy-policy', 'Seller ও shop application-এর তথ্য কীভাবে সংগ্রহ, ব্যবহার ও সুরক্ষিত করা হয়।',
E'১. এই নীতিমালা\n\nএই Seller Privacy Policy Bikrikoro.com-এর seller account, shop application এবং seller verification process-এর ক্ষেত্রে প্রযোজ্য।\n\n২. আমরা যে তথ্য সংগ্রহ করতে পারি\n\nPersonal information: নাম, ফোন নম্বর, email, profile photo এবং address।\n\nSeller ও business information: shop name, shop description, business address, business registration information যদি seller প্রদান করেন, এবং seller category।\n\nVerification information: NID বা অন্য government-issued identification, business registration বা shop ownership/authorization document—যে তথ্য verification-এর জন্য seller জমা দেন।\n\nPlatform ও transaction information: account activity, login এবং device-related technical information, order information, payment status, seller earnings, refund ও dispute information।\n\n৩. কেন এই তথ্য ব্যবহার করা হয়\n\nBikrikoro এই তথ্য seller account পরিচালনা, shop application review, seller identity বা business verification, fake/scam seller ও fraud প্রতিরোধ, marketplace security, buyer-seller transaction, customer support, dispute investigation এবং আইনগত বা compliance requirement পূরণে ব্যবহার করতে পারে।\n\n৪. Verification document কেন প্রয়োজন\n\nBikrikoro নিরাপদ marketplace environment বজায় রাখতে নির্দিষ্ট seller-এর কাছ থেকে পরিচয় বা ব্যবসায়িক তথ্যের প্রমাণ চাইতে পারে। এই documents শুধুমাত্র seller verification, fraud prevention, security, compliance এবং related marketplace operations-এর উদ্দেশ্যে ব্যবহার করা হবে।\n\n৫. তথ্য কার সঙ্গে শেয়ার হতে পারে\n\nBuyer-এর কাছে সাধারণত seller-এর public shop information-ই দেখানো হবে। Verification document public করা হবে না। প্রয়োজন হলে payment provider, hosting/service provider, verification provider বা আইনগত কর্তৃপক্ষের সঙ্গে প্রয়োজনীয় তথ্য শেয়ার হতে পারে। আইনগত প্রয়োজন ছাড়া personal information বিক্রি করা হবে না।\n\n৬. Public ও private information\n\nPublic হতে পারে: shop name, shop logo, product information, shop description, seller rating/review এবং seller নিজে প্রকাশ করা public contact information।\n\nPrivate থাকবে: NID বা passport, verification document, personal identification information, internal verification record এবং sensitive account information।\n\n৭. তথ্য কতদিন রাখা হয়\n\nAccount পরিচালনা, verification, dispute resolution, security, fraud prevention এবং legal/compliance requirement পূরণের জন্য যতদিন প্রয়োজন ততদিন তথ্য রাখা হতে পারে। প্রয়োজন শেষ হলে applicable law ও operational requirement অনুযায়ী তথ্য মুছে বা anonymize করা হতে পারে।\n\n৮. Data security\n\nBikrikoro access control, secure storage, প্রযোজ্য ক্ষেত্রে encryption, unauthorized access প্রতিরোধ এবং internal access limitation ব্যবহার করে seller information সুরক্ষিত রাখার চেষ্টা করে।\n\n৯. Seller-এর অধিকার\n\nSeller তার সংরক্ষিত তথ্য সম্পর্কে জানতে, ভুল তথ্য সংশোধনের অনুরোধ করতে, applicable law অনুযায়ী deletion বা access request করতে এবং privacy-related প্রশ্ন করতে পারেন।\n\n১০. Cookies ও third-party service\n\nBikrikoro account, hosting, database, payment, email এবং security-এর জন্য ব্যবহৃত প্রয়োজনীয় service provider-এর সঙ্গে সীমিত তথ্য ব্যবহার করতে পারে। যেসব third-party service বাস্তবে ব্যবহৃত হয় না, সেগুলো এই policy-তে ধরে নেওয়া হয়নি।\n\n১১. Policy change ও যোগাযোগ\n\nBikrikoro প্রয়োজন অনুযায়ী এই policy update করতে পারে এবং updated version এই page-এ প্রকাশ করবে। Privacy-related প্রশ্নের জন্য info.bikrikoro@gmail.com-এ যোগাযোগ করুন। Website: bikrikoro.com',
'PUBLISHED', 'Seller Privacy Policy | Bikrikoro.com', 'Bikrikoro.com seller account, shop application, verification documents এবং seller information-এর privacy policy।', now()
where not exists (select 1 from public.admin_content where content_type='SELLER_PRIVACY' and slug='seller-privacy-policy');
